  background: linear-gradient(160deg, #1c1f27, #0e0f13);
  overflow: hidden;
  flex: none;
}
.deal-row .thumb svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.deal-row .info h4 {
  margin: 0 0 4px; font-size: 1rem; font-weight: 600;
}
.deal-row .info .meta { color: var(--text-dim); font-size: 0.82rem; }
.deal-row .price-block { text-align: right; }
.deal-row .price-block .now {
  font-family: "Fraunces", serif;
  font-weight: 600;
  font-size: 1.15rem;
  color: var(--accent);
}
.deal-row .price-block .was {
  display: block;
  color: var(--text-dim);
  text-decoration: line-through;
  font-size: 0.82rem;
}
.deal-row .price-block .save {
  display: inline-block;
  margin-top: 4px;
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent-2);
  font-weight: 700;
}

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 18px;
}
.editorial-grid > :nth-child(1) { grid-row: span 2; }

@media (max-width: 980px) {
  .editorial-grid {
    grid-template-columns: 1fr 1fr;
  }
  .editorial-grid > :nth-child(1) { grid-row: auto; grid-column: span 2; }
}
@media (max-width: 620px) {
  .editorial-grid {
    grid-template-columns: 1fr;
  }
  .editorial-grid > :nth-child(1) { grid-column: auto; }
}

.editorial-card {
  position: relative;
  display: flex; flex-direction: column;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  overflow: hidden;
  text-decoration: none;
  color: var(--text);
  transition: border-color .2s ease, transform .2s ease;
  min-height: 280px;
}
.editorial-card:hover { border-color: var(--line-strong); transform: translateY(-3px); }

.editorial-card .image {
  position: relative;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: var(--bg-2);
}
.editorial-card .image svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.editorial-card.feature .image { aspect-ratio: 4 / 5; }

.editorial-card .body {
  padding: 20px 22px 24px;
  display: flex; flex-direction: column;
  gap: 8px;
}
.editorial-card .cat {
  color: var(--accent);
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.editorial-card h3 {
  font-family: "Fraunces", serif;
  font-weight: 600;
  font-size: 1.25rem;
  line-height: 1.25;
  margin: 0;
  letter-spacing: -0.01em;
}
.editorial-card.feature h3 {
  font-size: clamp(1.6rem, 2.4vw, 2.05rem);
}
.editorial-card .excerpt {
  color: var(--text-muted);
  font-size: 0.95rem;
  margin: 4px 0 0;
}
.editorial-card .byline {
  color: var(--text-dim);
  font-size: 0.82rem;
  margin-top: auto;
  padding-top: 10px;
}
.editorial-card h3 a {
  color: var(--text);
  text-decoration: none;
}
.editorial-card h3 a::after {
  content: "";
  position: absolute; inset: 0;
}
.editorial-card:hover h3 a { color: var(--accent); }

/* ---------- Newsletter ---------- */
.newsletter {
  background: linear-gradient(160deg, #15171f 0%, #0a0a0c 100%);
  border-top: 1px solid var(--line);
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(20px, 3vw, 40px);
  align-items: center;
  padding-block: clamp(40px, 6vw, 80px);
}
@media (max-width: 760px) { .newsletter-inner { grid-template-columns: 1fr; } }

.newsletter h2 {
  font-family: "Fraunces", serif;
  font-weight: 600;
  font-size: clamp(1.6rem, 3vw, 2.25rem);
  margin: 0 0 10px;
  letter-spacing: -0.01em;
}
.newsletter p { color: var(--text-muted); margin: 0; }

.subscribe-form {
  display: flex; gap: 10px;
  background: var(--bg-1);
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  padding: 6px;
  max-width: 460px;
  margin-left: auto;
}
@media (max-width: 760px) { .subscribe-form { margin-left: 0; } }
.subscribe-form input {
  flex: 1;
  background: transparent;
  border: 0;
  color: var(--text);
  padding: 10px 14px;
  font-size: 0.95rem;
  min-width: 0;
}
.subscribe-form input::placeholder { color: var(--text-dim); }
.subscribe-form input:focus { outline: none; }
.subscribe-form input:focus-visible {
  box-shadow: none;
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 999px;
}
.subscribe-form button { white-space: nowrap; }
.form-note {
  color: var(--text-dim);
  font-size: 0.82rem;
  margin: 12px 0 0;
}
.form-status {
  margin-top: 10px;
  font-size: 0.92rem;
  color: var(--success);
}
.form-status[data-state="error"] { color: var(--danger); }

/* ---------- Footer ---------- */
.site-footer {
  background: var(--bg-0);
  border-top: 1px solid var(--line);
  color: var(--text-muted);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 36px;
  padding-block: 56px;
}
@media (max-width: 760px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid > :first-child { grid-column: span 2; }
}
.footer-grid h4 {
  color: var(--text);
  font-size: 0.85rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  margin: 0 0 14px;
}
.footer-grid ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 8px; }
.footer-grid a {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.92rem;
}
.footer-grid a:hover { color: var(--text); }

.footer-brand p { max-width: 38ch; font-size: 0.92rem; }
.socials {
  display: flex; gap: 8px; margin-top: 18px;
}
.socials a {
  width: 40px; height: 40px;
  border-radius: 999px;
  border: 1px solid var(--line);
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--text-muted);
}
.socials a:hover { color: var(--accent); border-color: var(--line-strong); }
.socials svg { width: 18px; height: 18px; }

.footer-bottom {
  border-top: 1px solid var(--line);
  padding: 18px 0;
  display: flex; flex-wrap: wrap; gap: 14px; align-items: center; justify-content: space-between;
  font-size: 0.82rem;
  color: var(--text-dim);
}
.legal-list { display: flex; gap: 16px; flex-wrap: wrap; list-style: none; padding: 0; margin: 0; }
.legal-list a { color: var(--text-dim); text-decoration: none; }
.legal-list a:hover { color: var(--text); }

/* ---------- Reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  * {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

/* ---------- Forced colors ---------- */
@media (forced-colors: active) {
  .btn, .icon-btn, .add-btn, .tab, .category-card, .product-card, .deal-row, .editorial-card {
    border: 1px solid CanvasText;
  }
  .tab[aria-selected="true"], .btn--primary { background: Highlight; color: HighlightText; }
}

/* SR-only utility */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}
