arguments.file_text:
/* ---------- Tokens ---------- */
:root {
  --bg-0: #0a0a0c;
  --bg-1: #111115;
  --bg-2: #16171c;
  --bg-3: #1d1f26;
  --bg-4: #262932;
  --line: #2b2e39;
  --line-strong: #3a3e4d;
  --text: #f1f1f3;
  --text-muted: #b6b8c2;
  --text-dim: #8a8d9a;
  --accent: #d4ff3a;     /* electric lime */
  --accent-ink: #0a0a0c;
  --accent-2: #ff7a59;   /* warm coral for editorial */
  --danger: #ff6b6b;
  --success: #6ee7a7;

  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 22px;

  --shadow-1: 0 1px 0 rgba(255,255,255,0.04) inset, 0 6px 20px rgba(0,0,0,0.35);
  --shadow-2: 0 10px 40px rgba(0,0,0,0.55);

  --container: 1240px;
  --gutter: clamp(16px, 3vw, 32px);

  --focus: 0 0 0 2px var(--bg-0), 0 0 0 4px var(--accent);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg-0);
  color: var(--text);
  font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
button { font-family: inherit; }

/* Background ambience */
body::before {
  content: "";
  position: fixed; inset: 0;
  pointer-events: none;
  background:
    radial-gradient(900px 500px at 12% -10%, rgba(212,255,58,0.08), transparent 60%),
    radial-gradient(700px 400px at 95% 8%, rgba(255,122,89,0.07), transparent 60%);
  z-index: 0;
}

#root { position: relative; z-index: 1; }

.boot {
  color: var(--text-dim);
  text-align: center;
  padding: 25vh 1rem;
  font-size: 0.95rem;
  letter-spacing: 0.04em;
}

/* ---------- Skip link ---------- */
.skip-link {
  position: absolute;
  left: -9999px;
  top: 8px;
  padding: 10px 14px;
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 600;
  border-radius: 8px;
  text-decoration: none;
  z-index: 200;
}
.skip-link:focus {
  left: 12px;
  outline: none;
  box-shadow: var(--focus);
}

/* ---------- Focus ---------- */
:where(a, button, input, select, textarea, [tabindex]):focus-visible {
  outline: none;
  box-shadow: var(--focus);
  border-radius: 6px;
}

/* ---------- Layout helpers ---------- */
.container {
  max-width: var(--container);
  margin: 0 auto;
  padding-inline: var(--gutter);
}

.section {
  padding-block: clamp(48px, 7vw, 96px);
  position: relative;
}

.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}
.section-head h2 {
  font-family: "Fraunces", Georgia, serif;
  font-weight: 600;
  font-size: clamp(1.7rem, 3.2vw, 2.4rem);
  letter-spacing: -0.01em;
  margin: 0 0 6px;
  line-height: 1.1;
}
.section-head .eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text-dim);
  font-size: 0.78rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  margin-bottom: 10px;
}
.section-head .eyebrow::before {
  content: "";
  width: 18px; height: 1px; background: var(--text-dim);
}
.section-head p {
  color: var(--text-muted);
  margin: 0;
  max-width: 50ch;
}
.section-head .head-link {
  flex: none;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 20px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: var(--bg-3);
  color: var(--text);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
  cursor: pointer;
  transition: transform .15s ease, background .15s ease, color .15s ease, border-color .15s ease;
  min-height: 44px;
}
.btn:hover { background: var(--bg-4); }
.btn:active { transform: translateY(1px); }

.btn--primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn--primary:hover { background: #c2ec24; }

.btn--ghost {
  background: transparent;
  border-color: var(--line-strong);
  color: var(--text);
}
.btn--ghost:hover { border-color: var(--text); background: rgba(255,255,255,0.03); }

.btn--sm { padding: 8px 14px; font-size: 0.85rem; min-height: 36px; }

/* Arrow link */
.arrow-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.92rem;
  border-bottom: 1px solid var(--line-strong);
  padding-bottom: 4px;
}
.arrow-link:hover { border-color: var(--accent); color: var(--accent); }
.arrow-link svg { transition: transform .2s ease; }
.arrow-link:hover svg { transform: translateX(3px); }

/* ---------- Top bar ---------- */
.announce {
  background: var(--bg-1);
  border-bottom: 1px solid var(--line);
  color: var(--text-muted);
  font-size: 0.82rem;
}
.announce-inner {
  display: flex; align-items: center; justify-content: center; gap: 12px;
  padding: 10px var(--gutter);
  text-align: center;
}
.announce strong { color: var(--text); font-weight: 600; }

/* ---------- Header ---------- */
.site-header {
  position: sticky; top: 0;
  z-index: 50;
  background: rgba(10,10,12,0.78);
  backdrop-filter: saturate(140%) blur(12px);
  -webkit-backdrop-filter: saturate(140%) blur(12px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 20px;
  padding: 14px var(--gutter);
  max-width: var(--container);
  margin: 0 auto;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--text);
  font-family: "Fraunces", Georgia, serif;
  font-weight: 700;
  font-size: 1.35rem;
  letter-spacing: -0.01em;
}
.brand-mark {
  width: 30px; height: 30px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, var(--accent), #88aa00 60%, #1a1a00);
  box-shadow: 0 0 0 1px rgba(255,255,255,0.06) inset;
}

.primary-nav ul {
  display: flex;
  gap: 4px;
  list-style: none;
  margin: 0; padding: 0;
  justify-content: center;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 14px;
  color: var(--text-muted);
  text-decoration: none;
  border-radius: 999px;
  font-weight: 500;
  font-size: 0.95rem;
}
.primary-nav a:hover { color: var(--text); background: var(--bg-2); }
.primary-nav a[aria-current="page"] {
  color: var(--text); background: var(--bg-3);
}

.header-actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.icon-btn {
  appearance: none;
  background: transparent;
  border: 1px solid transparent;
  color: var(--text);
  width: 42px; height: 42px;
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  cursor: pointer;
  position: relative;
}
.icon-btn:hover { background: var(--bg-2); }
.icon-btn svg { width: 20px; height: 20px; }
.icon-btn .badge {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 18px; height: 18px;
  padding: 0 5px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 0.7rem;
  font-weight: 700;
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  box-shadow: 0 0 0 2px var(--bg-0);
}

.menu-toggle { display: none; }

@media (max-width: 880px) {
  .header-inner { grid-template-columns: auto auto; }
  .primary-nav { display: none; }
  .primary-nav.open {
    display: block;
    position: absolute;
    top: 100%; left: 0; right: 0;
    background: var(--bg-1);
    border-bottom: 1px solid var(--line);
    padding: 8px var(--gutter) 16px;
  }
  .primary-nav.open ul {
    flex-direction: column;
    align-items: stretch;
    gap: 0;
  }
  .primary-nav.open a {
    padding: 14px 12px;
    border-radius: 8px;
  }
  .menu-toggle { display: inline-flex; }
}

/* ---------- Hero ---------- */
.hero {
  padding-block: clamp(48px, 8vw, 110px);
  position: relative;
  overflow: hidden;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: clamp(24px, 4vw, 56px);
  align-items: center;
}
@media (max-width: 880px) {
  .hero-grid { grid-template-columns: 1fr; }
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 6px 12px 6px 6px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  color: var(--text-muted);
  font-size: 0.8rem;
  letter-spacing: 0.06em;
}
.hero-eyebrow .pill {
  background: var(--accent);
  color: var(--accent-ink);
  padding: 3px 10px;
  border-radius: 999px;
  font-weight: 700;
  letter-spacing: 0.04em;
  font-size: 0.72rem;
  text-transform: uppercase;
}
.hero h1 {
  font-family: "Fraunces", Georgia, serif;
  font-weight: 600;
  font-size: clamp(2.4rem, 6vw, 4.6rem);
  line-height: 1.02;
  letter-spacing: -0.025em;
  margin: 18px 0 18px;
}
.hero h1 em {
  font-style: italic;
  color: var(--accent);
  font-weight: 500;
}
.hero p.lede {
  color: var(--text-muted);
  font-size: 1.08rem;
  max-width: 48ch;
  margin: 0 0 28px;
}
.hero-ctas {
  display: flex; flex-wrap: wrap; gap: 12px;
  margin-bottom: 36px;
}
.hero-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 18px;
  border-top: 1px solid var(--line);
  padding-top: 22px;
  max-width: 520px;
}
.hero-stats dt {
  font-family: "Fraunces", serif;
  font-size: 1.7rem;
  font-weight: 600;
  color: var(--text);
  margin: 0;
}
.hero-stats dd {
  margin: 4px 0 0;
  color: var(--text-dim);
  font-size: 0.82rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* Hero card visual */
.hero-visual {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: linear-gradient(155deg, #1f2129 0%, #0e0f13 100%);
  border: 1px solid var(--line);
  box-shadow: var(--shadow-2);
}
.hero-visual::after {
  content: "";
  position: absolute; inset: 0;
  background:
    radial-gradient(60% 60% at 70% 25%, rgba(212,255,58,0.18), transparent 70%),
    radial-gradient(40% 50% at 20% 90%, rgba(255,122,89,0.18), transparent 70%);
  pointer-events: none;
}
.hero-visual svg.product-art {
  position: absolute;
  inset: 0;
  width: 100%; height: 100%;
}
.hero-meta {
  position: absolute;
  left: 20px; bottom: 20px;
  right: 20px;
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px;
  background: rgba(10,10,12,0.65);
  backdrop-filter: blur(14px);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  padding: 14px 18px;
}
.hero-meta .name { font-weight: 600; }
.hero-meta .sub { color: var(--text-dim); font-size: 0.85rem; }
.hero-meta .price { font-weight: 700; font-family: "Fraunces", serif; font-size: 1.2rem; }

.hero-tag {
  position: absolute;
  top: 16px; left: 16px;
  padding: 6px 12px;
  background: rgba(10,10,12,0.7);
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
}

/* ---------- Category pills ---------- */
.categories {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 12px;
}
.category-card {
  display: flex; align-items: center; gap: 12px;
  padding: 16px;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  color: var(--text);
  text-decoration: none;
  transition: border-color .15s ease, transform .15s ease, background .15s ease;
}
.category-card:hover {
  border-color: var(--line-strong);
  background: var(--bg-2);
  transform: translateY(-2px);
}
.category-card .cat-icon {
  width: 42px; height: 42px;
  border-radius: 12px;
  background: linear-gradient(135deg, var(--bg-3), var(--bg-4));
  display: inline-flex; align-items: center; justify-content: center;
  flex: none;
}
.category-card .cat-icon svg { width: 22px; height: 22px; color: var(--accent); }
.category-card .cat-name { font-weight: 600; font-size: 0.98rem; }
.category-card .cat-count { color: var(--text-dim); font-size: 0.8rem; }

/* ---------- Product grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: clamp(14px, 2vw, 22px);
}
.product-card {
  position: relative;
  display: flex; flex-direction: column;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color .2s ease, transform .2s ease;
}
.product-card:hover { border-color: var(--line-strong); transform: translateY(-3px); }

.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  background: linear-gradient(160deg, #20232c 0%, #0f1014 100%);
  overflow: hidden;
}
.product-media svg.product-art { position: absolute; inset: 0; width: 100%; height: 100%; }
.product-media .glow {
  position: absolute; inset: 0;
  background: radial-gradient(60% 60% at 60% 30%, rgba(212,255,58,0.12), transparent 70%);
  pointer-events: none;
}

.product-tag {
  position: absolute; top: 12px; left: 12px;
  background: rgba(10,10,12,0.72);
  border: 1px solid var(--line);
  color: var(--text-muted);
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 4px 9px;
  border-radius: 999px;
}
.product-tag--new { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
.product-tag--sale { background: var(--accent-2); color: #1a0a06; border-color: transparent; }

.wishlist {
  position: absolute; top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(10,10,12,0.72);
  border: 1px solid var(--line);
  color: var(--text);
  display: inline-flex; align-items: center; justify-content: center;
  cursor: pointer;
}
.wishlist:hover { color: var(--accent-2); }
.wishlist[aria-pressed="true"] { color: var(--accent-2); border-color: var(--accent-2); }
.wishlist svg { width: 18px; height: 18px; }

.product-body {
  padding: 14px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.product-cat {
  color: var(--text-dim);
  font-size: 0.74rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.product-name {
  margin: 0;
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.3;
}
.product-name a {
  color: var(--text);
  text-decoration: none;
}
.product-name a::after {
  content: "";
  position: absolute; inset: 0;
}
.product-name a:hover { color: var(--accent); }

.product-rating {
  display: inline-flex; align-items: center; gap: 6px;
  color: var(--text-muted);
  font-size: 0.82rem;
}
.stars { color: var(--accent); letter-spacing: 1px; }

.product-foot {
  margin-top: auto;
  padding-top: 8px;
  display: flex; align-items: center; justify-content: space-between;
  gap: 10px;
}
.product-price {
  font-family: "Fraunces", serif;
  font-weight: 600;
  font-size: 1.15rem;
}
.product-price .was {
  color: var(--text-dim);
  text-decoration: line-through;
  margin-right: 8px;
  font-size: 0.95rem;
  font-weight: 400;
}
.product-price .now--sale { color: var(--accent-2); }

.add-btn {
  position: relative;
  z-index: 2;
  appearance: none;
  background: var(--bg-3);
  border: 1px solid var(--line-strong);
  color: var(--text);
  padding: 8px 14px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.85rem;
  cursor: pointer;
  min-height: 36px;
  display: inline-flex; align-items: center; gap: 6px;
}
.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
.add-btn[data-added="true"] { background: var(--success); color: #08210f; border-color: transparent; }
.add-btn svg { width: 16px; height: 16px; }

/* ---------- Filters/Tabs ---------- */
.tabs {
  display: inline-flex;
  background: var(--bg-1);
  border: 1px solid var(--line);
  padding: 4px;
  border-radius: 999px;
  gap: 2px;
  flex-wrap: wrap;
}
.tab {
  appearance: none;
  background: transparent;
  border: 0;
  padding: 8px 16px;
  border-radius: 999px;
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.9rem;
  cursor: pointer;
  min-height: 36px;
}
.tab:hover { color: var(--text); }
.tab[aria-selected="true"] {
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 600;
}

/* ---------- Deals ---------- */
.deals {
  background:
    linear-gradient(180deg, transparent, rgba(255,122,89,0.04) 50%, transparent),
    var(--bg-0);
  border-block: 1px solid var(--line);
}
.deals-grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: clamp(16px, 2.5vw, 28px);
}
@media (max-width: 880px) { .deals-grid { grid-template-columns: 1fr; } }

.deal-hero {
  position: relative;
  padding: clamp(24px, 4vw, 44px);
  border-radius: var(--radius-lg);
  background:
    radial-gradient(120% 100% at 100% 0%, rgba(255,122,89,0.25), transparent 55%),
    linear-gradient(160deg, #2a1410 0%, #120808 80%);
  border: 1px solid #3a1a13;
  overflow: hidden;
  min-height: 380px;
  display: flex; flex-direction: column; justify-content: space-between;
  gap: 24px;
}
.deal-hero::after {
  content: "";
  position: absolute; right: -60px; bottom: -80px;
  width: 360px; height: 360px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255,122,89,0.45), transparent 60%);
  filter: blur(20px);
  pointer-events: none;
}
.deal-hero .label {
  display: inline-block;
  background: var(--accent-2);
  color: #1a0a06;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 0.78rem;
  padding: 6px 12px;
  border-radius: 999px;
  align-self: flex-start;
}
.deal-hero h3 {
  font-family: "Fraunces", serif;
  font-weight: 600;
  font-size: clamp(1.8rem, 3.4vw, 2.6rem);
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin: 16px 0 10px;
  position: relative;
}
.deal-hero p {
  color: var(--text-muted);
  margin: 0;
  max-width: 40ch;
  position: relative;
}
.deal-cta { display: flex; gap: 12px; flex-wrap: wrap; align-items: center; position: relative; }

.countdown {
  display: inline-flex;
  gap: 8px;
  margin-top: 4px;
  position: relative;
}
.countdown li {
  list-style: none;
  background: rgba(0,0,0,0.4);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 10px;
  padding: 10px 12px;
  min-width: 64px;
  text-align: center;
}
.countdown .num {
  display: block;
  font-family: "Fraunces", serif;
  font-size: 1.6rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.countdown .lbl {
  display: block;
  font-size: 0.7rem;
  color: var(--text-dim);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  margin-top: 6px;
}

.deal-list {
  display: grid; gap: 14px;
  align-content: start;
}
.deal-row {
  display: grid;
  grid-template-columns: 96px 1fr auto;
  gap: 16px;
  align-items: center;
  padding: 14px;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  text-decoration: none;
  color: var(--text);
  transition: border-color .15s ease, background .15s ease;
}
.deal-row:hover { border-color: var(--line-strong); background: var(--bg-2); }
.deal-row .thumb {
  position: relative;
  width: 96px; height: 96px;
  border-radius: 12px;
  background: linear-gradient(160deg, #1c1f27, #0e0f13);
  overflow: hidden;
  flex: none;
}
.deal-row .thumb svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.deal-row .info h4 {
  margin: 0 0 4px; font-size: 1rem; font-weight: 600;
}
.deal-row .info .meta { color: var(--text-dim); font-size: 0.82rem; }
.deal-row .price-block { text-align: right; }
.deal-row .price-block .now {
  font-family: "Fraunces", serif;
  font-weight: 600;
  font-size: 1.15rem;
  color: var(--accent);
}
.deal-row .price-block .was {
  display: block;
  color: var(--text-dim);
  text-decoration: line-through;
  font-size: 0.82rem;
}
.deal-row .price-block .save {
  display: inline-block;
  margin-top: 4px;
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent-2);
  font-weight: 700;
}

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 18px;
}
.editorial-grid > :nth-child(1) { grid-row: span 2; }

@media (max-width: 980px) {
  .editorial-grid {
    grid-template-columns: 1fr 1fr;
  }
  .editorial-grid > :nth-child(1) { grid-row: auto; grid-column: span 2; }
}
@media (max-width: 620px) {
  .editorial-grid {
    grid-template-columns: 1fr;
  }
  .editorial-grid > :nth-child(1) { grid-column: auto; }
}

.editorial-card {
  position: relative;
  display: flex; flex-direction: column;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  overflow: hidden;
  text-decoration: none;
  color: var(--text);
  transition: border-color .2s ease, transform .2s ease;
  min-height: 280px;
}
.editorial-card:hover { border-color: var(--line-strong); transform: translateY(-3px); }

.editorial-card .image {
  position: relative;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: var(--bg-2);
}
.editorial-card .image svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.editorial-card.feature .image { aspect-ratio: 4 / 5; }

.editorial-card .body {
