  font-family: "Fraunces", serif;
  font-weight: 600;
  font-size: 1.25rem;
  line-height: 1.25;
  margin: 0;
  letter-spacing: -0.01em;
}
.editorial-card.feature h3 {
  font-size: clamp(1.6rem, 2.4vw, 2.05rem);
}
