  font-size: 0.82rem;
  margin-top: auto;
  padding-top: 10px;
}
.editorial-card h3 a {
  color: var(--text);
  text-decoration: none;
}
.editorial-card h3 a::after {
  content: "";
  position: absolute; inset: 0;
}
.editorial-card:hover h3 a { color: var(--accent); }

