  aspect-ratio: 4 / 5;
  background: linear-gradient(160deg, #20232c 0%, #0f1014 100%);
  overflow: hidden;
}
.product-media svg.product-art { position: absolute; inset: 0; width: 100%; height: 100%; }
.product-media .glow {
  position: absolute; inset: 0;
  background: radial-gradient(60% 60% at 60% 30%, rgba(212,255,58,0.12), transparent 70%);
  pointer-events: none;
}

.product-tag {
  position: absolute; top: 12px; left: 12px;
  background: rgba(10,10,12,0.72);
  border: 1px solid var(--line);
  color: var(--text-muted);
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 4px 9px;
  border-radius: 999px;
}
.product-tag--new { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
.product-tag--sale { background: var(--accent-2); color: #1a0a06; border-color: transparent; }

.wishlist {
  position: absolute; top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(10,10,12,0.72);
  border: 1px solid var(--line);
  color: var(--text);
  display: inline-flex; align-items: center; justify-content: center;
  cursor: pointer;
}
.wishlist:hover { color: var(--accent-2); }
.wishlist[aria-pressed="true"] { color: var(--accent-2); border-color: var(--accent-2); }
.wishlist svg { width: 18px; height: 18px; }

.product-body {
  padding: 14px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.product-cat {
  color: var(--text-dim);
  font-size: 0.74rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.product-name {
  margin: 0;
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.3;
}
.product-name a {
  color: var(--text);
  text-decoration: none;
}
.product-name a::after {
  content: "";
  position: absolute; inset: 0;
}
.product-name a:hover { color: var(--accent); }

.product-rating {
  display: inline-flex; align-items: center; gap: 6px;
  color: var(--text-muted);
  font-size: 0.82rem;
}
.stars { color: var(--accent); letter-spacing: 1px; }

.product-foot {
  margin-top: auto;
  padding-top: 8px;
  display: flex; align-items: center; justify-content: space-between;
  gap: 10px;
}
.product-price {
  font-family: "Fraunces", serif;
  font-weight: 600;
  font-size: 1.15rem;
}
.product-price .was {
  color: var(--text-dim);
  text-decoration: line-through;
  margin-right: 8px;
  font-size: 0.95rem;
  font-weight: 400;
}
.product-price .now--sale { color: var(--accent-2); }

.add-btn {
  position: relative;
  z-index: 2;
  appearance: none;
  background: var(--bg-3);
  border: 1px solid var(--line-strong);
  color: var(--text);
  padding: 8px 14px;
