    case "audio": return <svg {...common}><path d="M9 18V6l12-2v12"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/></svg>;
    case "lamp": return <svg {...common}><path d="M9 3h6l3 7H6l3-7Z"/><path d="M12 10v8"/><path d="M9 21h6"/></svg>;
    case "chair": return <svg {...common}><path d="M5 11V7a3 3 0 0 1 3-3h8a3 3 0 0 1 3 3v4"/><path d="M4 11h16l-1 5H5l-1-5Z"/><path d="M7 16v4M17 16v4"/></svg>;
    case "cup": return <svg {...common}><path d="M5 8h12v6a5 5 0 0 1-5 5h-2a5 5 0 0 1-5-5V8Z"/><path d="M17 10h2a2 2 0 0 1 0 4h-2"/></svg>;
    case "speaker": return <svg {...common}><rect x="6" y="3" width="12" height="18" rx="2"/><circle cx="12" cy="9" r="2"/><circle cx="12" cy="15" r="3"/></svg>;
    case "watch": return <svg {...common}><rect x="7" y="7" width="10" height="10" rx="2"/><path d="M9 7V4h6v3M9 17v3h6v-3"/></svg>;
    case "instagram": return <svg {...common}><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r=".8" fill="currentColor"/></svg>;
    case "twitter": return <svg {...common}><path d="M4 4l7 9-7 7h2l6-6 4.5 6H21l-7.5-9.5L20.5 4H18l-5 5-3.5-5H4Z" fill="currentColor" stroke="none"/></svg>;
    case "youtube": return <svg {...common}><rect x="3" y="6" width="18" height="12" rx="3"/><path d="m11 9 4 3-4 3V9Z" fill="currentColor" stroke="none"/></svg>;
    case "pinterest": return <svg {...common}><circle cx="12" cy="12" r="9"/><path d="M11 7c3 0 5 1.8 5 4.3 0 2.6-1.7 4.4-3.8 4.4-1 0-1.9-.5-2.2-1.2 0 0-.5 2-.6 2.4-.2.7-.7 1.5-1 2"/></svg>;
    default: return null;
  }
};

