        <path d="M70 30 L130 30 L150 80 L50 80 Z" fill={`${b}`} fillOpacity=".15"/>
        <rect x="96" y="80" width="8" height="60" fill={a}/>
        <ellipse cx="100" cy="148" rx="36" ry="6" fill={a}/>
        <circle cx="100" cy="60" r="22" fill={b} fillOpacity=".5"/>
