    ),
    // Chair
    (
      <g key="ch">
        <rect x="50" y="40" width="100" height="70" rx="12" fill={a}/>
        <rect x="50" y="100" width="100" height="20" fill={b} fillOpacity=".25"/>
        <rect x="58" y="120" width="6" height="32" fill={a}/>
