                {i < 2 && <p className="excerpt">{post.excerpt}</p>}
                <span className="byline">By {post.author} · {post.date}</span>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

function Newsletter() {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState({ state: "idle", msg: "" });
  const inputId = useId();
  const noteId = useId();
  const statusId = useId();

  const submit = (e) => {
    e.preventDefault();
    const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    if (!ok) {
      setStatus({ state: "error", msg: "Please enter a valid email address." });
      return;
    }
    setStatus({ state: "ok", msg: `Thanks — we'll keep ${email} in the loop.` });
    setEmail("");
  };

  return (
    <section className="section newsletter" id="newsletter" aria-labelledby="nl-heading">
      <div className="container newsletter-inner">
        <div>
          <h2 id="nl-heading">Quiet updates, once a month.</h2>
          <p>New arrivals, behind-the-scenes from the studio, and early access to deals — no clutter.</p>
        </div>
        <div>
          <form className="subscribe-form" onSubmit={submit} noValidate aria-describedby={`${noteId} ${statusId}`}>
            <label htmlFor={inputId} className="sr-only">Email address</label>
            <input
              id={inputId}
              type="email"
              required
              autoComplete="email"
              placeholder="you@domain.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              aria-invalid={status.state === "error"}
            />
            <button className="btn btn--primary" type="submit">Subscribe</button>
          </form>
          <p id={noteId} className="form-note">By subscribing you agree to our privacy policy. Unsubscribe anytime.</p>
          <p
            id={statusId}
            className="form-status"
            data-state={status.state}
            role="status"
            aria-live="polite"
          >
            {status.msg}
          </p>
        </div>
      </div>
    </section>
  );
}

function Footer() {
  const groups = [
    { title: "Shop", links: ["Audio", "Lighting", "Furniture", "Accessories", "Gift cards"] },
    { title: "Support", links: ["Help center", "Shipping", "Returns", "Order status", "Contact"] },
    { title: "Company", links: ["About", "Sustainability", "Careers", "Press", "Stores"] },
  ];
  return (
    <footer className="site-footer" id="about">
      <div className="container">
        <div className="footer-grid">
          <div className="footer-brand">
            <a className="brand" href="#home" aria-label="Nocturne — home">
              <span className="brand-mark" aria-hidden="true"></span>
              <span>Nocturne</span>
            </a>
            <p>Modern goods for the after hours. Designed in Brooklyn, made with partners we visit in person.</p>
            <div className="socials" aria-label="Social media">
              <a href="#instagram" aria-label="Instagram"><Icon name="instagram" /></a>
              <a href="#twitter" aria-label="Twitter"><Icon name="twitter" /></a>
              <a href="#youtube" aria-label="YouTube"><Icon name="youtube" /></a>
              <a href="#pinterest" aria-label="Pinterest"><Icon name="pinterest" /></a>
            </div>
          </div>
          {groups.map(g => (
            <nav key={g.title} aria-label={g.title}>
              <h4>{g.title}</h4>
              <ul>
                {g.links.map(l => <li key={l}><a href={`#${l.toLowerCase().replace(/\s+/g, "-")}`}>{l}</a></li>)}
              </ul>
            </nav>
          ))}
        </div>
        <div className="footer-bottom">
          <span>© {new Date().getFullYear()} Nocturne Goods, Inc. All rights reserved.</span>
          <ul className="legal-list">
            <li><a href="#privacy">Privacy</a></li>
            <li><a href="#terms">Terms</a></li>
            <li><a href="#accessibility">Accessibility</a></li>
            <li><a href="#cookies">Cookie settings</a></li>
          </ul>
        </div>
      </div>
    </footer>
  );
}

/* ---------- App ---------- */
function App() {
  const [wishlist, setWishlist] = useState(() => new Set());
  const [cart, setCart] = useState([]);
  const [addedIds, setAddedIds] = useState(() => new Set());
  const addedTimers = useRef({});

  const onWishlist = (id) => {
    setWishlist(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };

  const onAdd = (product) => {
    setCart(prev => [...prev, product]);
    setAddedIds(prev => new Set(prev).add(product.id));
    clearTimeout(addedTimers.current[product.id]);
    addedTimers.current[product.id] = setTimeout(() => {
      setAddedIds(prev => {
        const n = new Set(prev); n.delete(product.id); return n;
      });
    }, 1600);
  };

  return (
    <>
      <AnnouncementBar />
      <Header cartCount={cart.length} wishlistCount={wishlist.size} />
      <main id="main" tabIndex={-1}>
        <Hero />
        <Categories />
        <FeaturedProducts
          wishlist={wishlist}
          addedIds={addedIds}
          onWishlist={onWishlist}
          onAdd={onAdd}
        />
        <Deals onAdd={onAdd} />
        <Editorial />
        <Newsletter />
      </main>
      <Footer />
    </>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<App />);
document.getElementById("root").removeAttribute("aria-busy");
