    ),
    // Chair
    (
      <g key="ch">
        <rect x="50" y="40" width="100" height="70" rx="12" fill={a}/>
        <rect x="50" y="100" width="100" height="20" fill={b} fillOpacity=".25"/>
        <rect x="58" y="120" width="6" height="32" fill={a}/>
        <rect x="136" y="120" width="6" height="32" fill={a}/>
      </g>
    ),
    // Mug
    (
      <g key="mug">
        <rect x="62" y="50" width="68" height="80" rx="8" fill={a}/>
        <path d="M130 70 q22 0 22 22 t-22 22" fill="none" stroke={a} strokeWidth="8"/>
        <rect x="62" y="70" width="68" height="10" fill={b} fillOpacity=".5"/>
      </g>
    ),
    // Speaker
    (
      <g key="sp">
        <rect x="60" y="20" width="80" height="130" rx="10" fill={a}/>
        <circle cx="100" cy="55" r="12" fill={c}/>
        <circle cx="100" cy="55" r="6" fill={b}/>
        <circle cx="100" cy="105" r="22" fill={c}/>
        <circle cx="100" cy="105" r="14" fill={b} fillOpacity=".7"/>
      </g>
    ),
    // Watch
    (
      <g key="w">
        <rect x="80" y="20" width="40" height="20" rx="6" fill={a}/>
        <rect x="80" y="130" width="40" height="20" rx="6" fill={a}/>
        <rect x="68" y="40" width="64" height="90" rx="14" fill={a}/>
        <rect x="76" y="48" width="48" height="74" rx="8" fill={c}/>
        <circle cx="100" cy="85" r="4" fill={b}/>
