.section-head p {
  color: var(--text-muted);
  margin: 0;
  max-width: 50ch;
}
.section-head .head-link {
  flex: none;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 20px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: var(--bg-3);
  color: var(--text);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
  cursor: pointer;
  transition: transform .15s ease, background .15s ease, color .15s ease, border-color .15s ease;
  min-height: 44px;
}
.btn:hover { background: var(--bg-4); }
.btn:active { transform: translateY(1px); }

.btn--primary {
