  text-decoration: none;
  border-radius: 999px;
  font-weight: 500;
  font-size: 0.95rem;
}
.primary-nav a:hover { color: var(--text); background: var(--bg-2); }
.primary-nav a[aria-current="page"] {
  color: var(--text); background: var(--bg-3);
}

.header-actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.icon-btn {
