  margin: 18px 0 18px;
}
.hero h1 em {
  font-style: italic;
  color: var(--accent);
  font-weight: 500;
}
.hero p.lede {
  color: var(--text-muted);
  font-size: 1.08rem;
  max-width: 48ch;
  margin: 0 0 28px;
}
.hero-ctas {
  display: flex; flex-wrap: wrap; gap: 12px;
  margin-bottom: 36px;
}
.hero-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
