function App() {
  const [wishlist, setWishlist] = useState(() => new Set());
  const [cart, setCart] = useState([]);
  const [addedIds, setAddedIds] = useState(() => new Set());
  const addedTimers = useRef({});

  const onWishlist = (id) => {
    setWishlist(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };

  const onAdd = (product) => {
    setCart(prev => [...prev, product]);
    setAddedIds(prev => new Set(prev).add(product.id));
    clearTimeout(addedTimers.current[product.id]);
    addedTimers.current[product.id] = setTimeout(() => {
      setAddedIds(prev => {
        const n = new Set(prev); n.delete(product.id); return n;
      });
    }, 1600);
  };

  return (
    <>
      <AnnouncementBar />
      <Header cartCount={cart.length} wishlistCount={wishlist.size} />
      <main id="main" tabIndex={-1}>
        <Hero />
        <Categories />
        <FeaturedProducts
          wishlist={wishlist}
          addedIds={addedIds}
          onWishlist={onWishlist}
          onAdd={onAdd}
        />
        <Deals onAdd={onAdd} />
        <Editorial />
        <Newsletter />
      </main>
      <Footer />
    </>
  );
}

