  const statusId = useId();

  const submit = (e) => {
    e.preventDefault();
    const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    if (!ok) {
      setStatus({ state: "error", msg: "Please enter a valid email address." });
      return;
    }
    setStatus({ state: "ok", msg: `Thanks — we'll keep ${email} in the loop.` });
    setEmail("");
